  },
}
```

**注意：** 每个账户需要自己的令牌（每个频道一个令牌）。

```json5
{
  channels: {
    twitch: {
      accounts: {
        default: {
          allowedRoles: ["moderator", "vip"],
        },
      },
    },
  },
}
```

```json5
{
