    web: {
      search: {
        enabled: true,
        provider: "perplexity",
      },
    },
  },
  plugins: {
    entries: {
      perplexity: {
        config: {
          webSearch: {
            // API 密钥（如果设置了 OPENROUTER_API_KEY 或 PERPLEXITY_API_KEY 则可选）
            apiKey: "sk-or-v1-...",
            // 基础 URL（如果省略则根据密钥感知默认值）
            baseUrl: "https://openrouter.ai/api/v1",
